            PSoundManager->StopMusic(fade_times.FadeOutMS);
        else
            PlayMusic(music_id, fade_times, sound_def.MusicSetEntries[new_state.GetActiveSet()].LoopCount);
    } else {
        PSoundManager->StopMusic(fade_times.FadeOutMS);
    }
    CurrentState = new_state;
}

